function getClipboardImageFiles(event) {
    const clipboardItems = Array.from(event?.clipboardData?.items || []);
    const itemFiles = clipboardItems
        .filter((item) => item.kind === "file" && String(item.type || "").startsWith("image/"))
        .map((item) => item.getAsFile())
        .filter(Boolean);

    if (itemFiles.length > 0) return itemFiles;

    return Array.from(event?.clipboardData?.files || [])
        .filter((file) => String(file?.type || "").startsWith("image/"));
}

function readFileAsDataUrl(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = () => reject(reader.error || new Error("image_read_failed"));
        reader.readAsDataURL(file);
    });
}

function getPasteSelection(event, fallbackText = "") {
    const target = event?.target;
    if (
        target
        && typeof target.selectionStart === "number"
        && typeof target.selectionEnd === "number"
    ) {
        return {
            start: target.selectionStart,
            end: target.selectionEnd,
            target,
        };
    }

    return {
        start: String(fallbackText || "").length,
        end: String(fallbackText || "").length,
        target: null,
    };
}

async function insertPastedImagesIntoMarkdown(event, { value = "", onChange } = {}) {
    const files = getClipboardImageFiles(event);
    if (!files.length || typeof onChange !== "function") {
        return false;
    }

    event.preventDefault();
    const { start, end, target } = getPasteSelection(event, value);
    const markdownImages = await Promise.all(
        files.map(async (file, index) => {
            const dataUrl = await readFileAsDataUrl(file);
            const extension = String(file.type || "image/png").split("/")[1] || "png";
            const fallbackName = `pasted-image-${index + 1}.${extension}`;
            const altText = String(file.name || fallbackName).replace(/[\[\]\n\r]/g, " ");
            return `![${altText}](${dataUrl})`;
        })
    );

    const currentValue = String(value || "");
    const needsLeadingBreak = start > 0 && !currentValue.slice(0, start).endsWith("\n");
    const needsTrailingBreak = end < currentValue.length && !currentValue.slice(end).startsWith("\n");
    const insertion = `${needsLeadingBreak ? "\n\n" : ""}${markdownImages.join("\n\n")}${needsTrailingBreak ? "\n\n" : ""}`;
    const nextValue = `${currentValue.slice(0, start)}${insertion}${currentValue.slice(end)}`;

    onChange(nextValue);

    if (target && typeof target.setSelectionRange === "function") {
        window.setTimeout(() => {
            const cursor = start + insertion.length;
            target.focus();
            target.setSelectionRange(cursor, cursor);
        }, 0);
    }

    return true;
}

export {
    insertPastedImagesIntoMarkdown,
};
